const stage=$input.first().json;
const parent=$('Create T1 Parent Run').first().json;
const errors=[];
if(stage.schema_version!=='1.0.0') errors.push('stage schema_version');
if(stage.run_id!==parent.run_id) errors.push('Requirement Extractor run_id mismatch');
if(stage.stage!=='requirement_extraction'||stage.execution_status!=='passed'||stage.decision!=='continue'||stage.next_route!=='gap_analysis') errors.push('Requirement Extractor route invalid');
if(stage.groundedness_percent!==100) errors.push('Requirement Extractor groundedness must be 100');
if(stage.observability?.parent_trace_id!==parent.orchestration_context.parent_trace_id) errors.push('Requirement Extractor parent_trace_id mismatch');
if(!stage.observability?.ingestion_accepted) errors.push('Requirement Extractor Langfuse ingestion not accepted');
if(stage.output?.run_id!==parent.run_id) errors.push('Extraction output run_id mismatch');
if(errors.length) throw new Error('Requirement Extraction stage validation failed: '+errors.join('; '));
return [{json:{schema_version:'1.0.0',run_id:parent.run_id,extraction:stage.output,orchestration_context:{parent_trace_id:parent.orchestration_context.parent_trace_id,test_id:'T1',environment:'connected-canary'},requirement_extraction_stage:stage}}];

